// This is a test method because of the test prefix.
[Hookable(false)]
public void testCollectorInitialization()
{

    TFMLogicComponentDimensions     dimComponent    = new TFMLogicComponentDimensions();
    TFMRegistrationCollectors       collectors      = dimComponent.registrationCollectors();
    int                             counter         = 0;
    str                             times           = int2Str(DateTimeUtil::getTimeNow(Timezone::GMTMINUS0300GREENLAND));

    while (counter < 1000)
    {
        this.copyCollectors(collectors);
        counter++;
    }
    times           += ' ' + int2Str(DateTimeUtil::getTimeNow(Timezone::GMTMINUS0300GREENLAND));
    counter = 0;
    while (counter < 1000)
    {
        dimComponent.registrationCollectors();
        counter++;
    }

    times           += ' ' + int2Str(DateTimeUtil::getTimeNow(Timezone::GMTMINUS0300GREENLAND));
    this.assertTrue(false,times);
}

protected TFMRegistrationCollector copyCollector(TFMRegistrationCollector _fromCol)
{        
    TFMRegistrationCollector                toCol;
    SetEnumerator                           parmMethods;
    SysDictClass                            sdc;

    sdc = new SysDictClass(classIdGet(_fromCol));
    toCol = sdc.makeObject();
    parmMethods = TFMFormLookupHelper::parmMethodsOnClass(sdc.id()).getEnumerator();
    while (parmMethods.moveNext())
    {
        sdc.callObject(parmMethods.current(),toCol,sdc.callObject(parmMethods.current(),_fromCol));
    }

    return toCol;
}

protected TFMRegistrationCollectors copyCollectors(TFMRegistrationCollectors _collectors)
{
    TFMRegistrationCollectors       collectors  = TFMRegistrationCollectors::Construct();
    MapEnumerator                   mEnum       = _collectors.collectorMap().getEnumerator();
    TFMRegistrationCollector        col;
    while (mEnum.moveNext())
    {
        col = this.copyCollector(mEnum.currentValue());
        collectors.addCollector(col);
    }
    return collectors;
}

